cstep_preserves_activation_trace_repr.statement:
\<lbrakk>wf_compile_input \<G> \<Pi> ps;
 \<G>,compile_prog \<Pi> ps \<turnstile> cf \<rightarrow>\<^sub>c cf';
 activation_trace_repr \<G> (compile_prog \<Pi> ps) S cf t\<rbrakk>
\<Longrightarrow> \<exists>t'.
                     activation_trace_repr \<G> (compile_prog \<Pi> ps) S
                      cf' t'

node_collect_semantic_postfix.statement:
\<lbrakk>S0.0 \<subseteq> B (cfg_entry g);
 \<And>u a w s s'.
    \<lbrakk>(u, a, w) \<in> intra g; s \<in> B u;
     s' \<in> edge_step a s\<rbrakk>
    \<Longrightarrow> s' \<in> B w;
 \<And>u dst pars args p cont s.
    \<lbrakk>(u, CallEdge dst pars args, FunctionEntry p, cont)
             \<in> calls g;
     s \<in> B u\<rbrakk>
    \<Longrightarrow> call_enter \<G> (CallEdge dst pars args) s
                      \<in> B (FunctionEntry p);
 \<And>cl dst pars args p cont s t.
    \<lbrakk>(cl, CallEdge dst pars args, FunctionEntry p, cont)
             \<in> calls g;
     s \<in> B cl; t \<in> B (FunctionResult p)\<rbrakk>
    \<Longrightarrow> combine_collect \<G> dst s t \<in> B cont\<rbrakk>
\<Longrightarrow> \<C>\<^bsub>\<G>,g,S0.0\<^esub> v \<subseteq> B v

pstep.Call.statement:
\<lbrakk>\<Pi> p = Some decl; length actuals = length (formals decl);
 distinct (formals decl);
 vals = map (\<lambda>e. \<lbrakk>e\<rbrakk>\<^sub>e s) actuals;
 callee = bind_formals (formals decl) vals (enter_state \<G> s)\<rbrakk>
\<Longrightarrow> \<G>,\<Pi> \<turnstile>
                  (com.Call dst p actuals, s, frs) \<rightarrow>\<^sub>p
                  (Seq (body decl) Restore, callee, Frame s dst # frs)

relc_branch_step_sound.statement:
\<lbrakk>s \<in> \<lbrakk>d\<rbrakk>;
 truthy (\<lbrakk>b\<rbrakk>\<^sub>e s) = pol\<rbrakk>
\<Longrightarrow> s \<in> \<lbrakk>relc_branch_step b pol d\<rbrakk>
